نقش سازمانی: مدیر مالی (cfo)

درخواست کاربر:
چرخهٔ تبدیل وجه نقد ما نسبت به فصل قبل 32 روز بلندتر شده و پول در حساب‌های دریافتنی خوابیده. دقیقاً کجای زنجیرهٔ نقد شکسته؟ می‌خواهم روی همان نقطه تمرکز کنم. (مدیر مالی — تولیدی کاشی و سرامیک)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "working_capital_breakdown",
      "description": "اجزای سرمایه در گردش و روزهای هر جزء",
      "dimensions": [
        "component",
        "period"
      ],
      "measures": [
        "amount",
        "days"
      ]
    },
    {
      "dataset": "receivables_aging",
      "description": "سن مطالبات به تفکیک مشتری و بازهٔ سنی",
      "dimensions": [
        "customer",
        "aging_bucket"
      ],
      "measures": [
        "balance"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "ccc",
      "description": "چرخهٔ تبدیل وجه نقد",
      "formula": "dio + dso - dpo",
      "unit": "روز",
      "dimensions": [
        "period"
      ]
    },
    {
      "metric": "dso",
      "description": "دورهٔ وصول مطالبات",
      "formula": "مطالبات / فروش روزانه",
      "unit": "روز",
      "dimensions": [
        "customer",
        "period"
      ]
    },
    {
      "metric": "dio",
      "description": "دورهٔ گردش موجودی",
      "formula": "موجودی / بهای تمام‌شدهٔ روزانه",
      "unit": "روز",
      "dimensions": [
        "period"
      ]
    },
    {
      "metric": "dpo",
      "description": "دورهٔ پرداخت بستانکاران",
      "formula": "بستانکاران / بهای تمام‌شدهٔ روزانه",
      "unit": "روز",
      "dimensions": [
        "period"
      ]
    }
  ],
  "business_context": [
    "شرکت تولیدی-بازرگانی میانه‌حجم؛ فروش عمدتاً نسیه به شرکت‌های صنعتی و بخشی خرد",
    "دورهٔ حسابداری ماهانه؛ گزارش‌ها تا پایان همان ماه در دسترس‌اند",
    "تأمین مالی اصلی از تسهیلات بانکی کوتاه‌مدت و اعتبار تأمین‌کنندگان"
  ]
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "ccc"
    ],
    "period": [
      "prev_quarter",
      "curr_quarter"
    ],
    "comparison": "quarter_over_quarter"
  }
}

TOOL_OBSERVATION:
{
  "ccc_days": {
    "prev_quarter": 26,
    "curr_quarter": 58,
    "change": 32
  }
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "working_capital_breakdown",
    "filters": {
      "period": [
        "prev_quarter",
        "curr_quarter"
      ]
    }
  }
}

TOOL_OBSERVATION:
{
  "components_days": {
    "dio": {
      "prev": 20,
      "curr": 24
    },
    "dso": {
      "prev": 34,
      "curr": 64
    },
    "dpo": {
      "prev": 28,
      "curr": 30
    }
  },
  "receivables_m_toman": {
    "prev": 442,
    "curr": 832
  }
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "receivables_aging",
    "filters": {
      "period": "curr_quarter"
    }
  }
}

TOOL_OBSERVATION:
{
  "aging_top": {
    "مشتری دولتی X": {
      "balance_m_toman": 557,
      "aging_days": 88,
      "share_of_new_sales_pct": 39
    },
    "سایر مشتریان": {
      "balance_m_toman": 275,
      "aging_days": 30
    }
  },
  "note": "قرارداد جدید سه‌ماهه با مشتری دولتی X با دورهٔ پرداخت ۹۰ روز و بدون ضمانت‌نامه بانکی؛ سهم 39٪ از فروش نسیهٔ جدید"
}

نقش سازمانی: مدیر مالی (cfo)

درخواست کاربر:
این ماه سود عملیاتی رشد کرده ولی موجودی نقد افت کرده. به نظر من سودآوری دارد نقدینگی ما را می‌خورد و باید فروش نسیه را متوقف کنیم. قبل از هر تصمیمی دلیل واقعی را بگو. (مدیر مالی — فرآوری لبنی)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "cash_flow_statement",
      "description": "صورت جریان وجوه نقد دوره به تفکیک بخش",
      "dimensions": [
        "period",
        "section"
      ],
      "measures": [
        "amount"
      ]
    },
    {
      "dataset": "monthly_cash_position",
      "description": "موجودی نقد پایان ماه",
      "dimensions": [
        "month"
      ],
      "measures": [
        "balance"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "operating_profit",
      "description": "سود عملیاتی",
      "formula": "حاشیهٔ ناخالص - هزینه‌های عملیاتی",
      "unit": "میلیون تومان",
      "dimensions": [
        "period"
      ]
    },
    {
      "metric": "cash_balance",
      "description": "موجودی نقد پایان دوره",
      "formula": "جمع ورودی و خروجی‌های نقد",
      "unit": "میلیون تومان",
      "dimensions": [
        "period"
      ]
    }
  ],
  "business_context": [
    "شرکت تولیدی-بازرگانی میانه‌حجم؛ فروش عمدتاً نسیه به شرکت‌های صنعتی و بخشی خرد",
    "دورهٔ حسابداری ماهانه؛ گزارش‌ها تا پایان همان ماه در دسترس‌اند"
  ]
}

TOOL_CALL:
{
  "tool": "compare_periods",
  "arguments": {
    "metric": "operating_profit",
    "period_a": "prev_month",
    "period_b": "curr_month"
  }
}

TOOL_OBSERVATION:
{
  "operating_profit": {
    "prev": 220,
    "curr": 259,
    "growth_m_toman": 39
  },
  "breakdown": {
    "رشد حاشیهٔ صادرات (افزایش نرخ ارز تسعیر)": 39
  }
}

TOOL_CALL:
{
  "tool": "get_timeseries",
  "arguments": {
    "metric": "cash_balance",
    "granularity": "month",
    "range": "last_2_months"
  }
}

TOOL_OBSERVATION:
{
  "cash_balance": {
    "prev_month_end": 99,
    "curr_month_end": 45,
    "drop_m_toman": 54
  },
  "outflows": {
    "خرید یکجای مواد اولیهٔ پروژهٔ جدید (انبارش)": 75,
    "پرداخت سود سالانهٔ تسهیلات": 22
  },
  "inflows": {
    "ورودی عملیاتی مازاد": 43
  }
}

