موجودی نقد ما چند ماه است کم می‌شود و یکی از اعضای هیئت می‌گوید تا سه ماه دیگر به صفر می‌رسد و باید فوری خط اعتباری بگیریم. این پیش‌بینی چقدر معتبر است؟ (مدیر مالی — تولیدی کاشی و سرامیک)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "monthly_cash_position",
      "description": "موجودی نقد پایان ماه",
      "dimensions": [
        "month"
      ],
      "measures": [
        "balance"
      ]
    },
    {
      "dataset": "cash_flow_statement",
      "description": "صورت جریان وجوه نقد دوره به تفکیک بخش",
      "dimensions": [
        "period",
        "section"
      ],
      "measures": [
        "amount"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "cash_balance",
      "description": "موجودی نقد پایان دوره",
      "formula": "جمع ورودی و خروجی‌های نقد",
      "unit": "میلیون تومان",
      "dimensions": [
        "period"
      ]
    }
  ],
  "business_context": [
    "شرکت تولیدی-بازرگانی میانه‌حجم؛ فروش عمدتاً نسیه به شرکت‌های صنعتی و بخشی خرد",
    "دورهٔ حسابداری ماهانه؛ گزارش‌ها تا پایان همان ماه در دسترس‌اند",
    "تأمین مالی اصلی از تسهیلات بانکی کوتاه‌مدت و اعتبار تأمین‌کنندگان"
  ]
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "cash_balance"
    ],
    "period": "last_4_months",
    "comparison": null
  }
}

TOOL_OBSERVATION:
{
  "cash_balance_monthly": [
    {
      "month": "مرداد",
      "end_balance_m_toman": 350
    },
    {
      "month": "شهریور",
      "end_balance_m_toman": 324
    }
  ]
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "cash_flow_statement",
    "filters": {
      "period": "last_4_months",
      "section": "operating"
    }
  }
}

نقش سازمانی: مدیر مالی (cfo)

