برای دو ماه آینده حدود 450 میلیون تومان نقد نیاز داریم. بین فاکتورینگ مطالبات و وام کوتاه‌مدت کدام از نظر مالی به صرفه‌تر است؟ (مدیر مالی — تولیدی قطعات خودرو)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "receivables_aging",
      "description": "سن مطالبات به تفکیک مشتری و بازهٔ سنی",
      "dimensions": [
        "customer",
        "aging_bucket"
      ],
      "measures": [
        "balance"
      ]
    },
    {
      "dataset": "monthly_cash_position",
      "description": "موجودی نقد پایان ماه",
      "dimensions": [
        "month"
      ],
      "measures": [
        "balance"
      ]
    },
    {
      "dataset": "budget_vs_actual",
      "description": "بودجه در برابر واقعی به تفکیک ردیف",
      "dimensions": [
        "line",
        "period"
      ],
      "measures": [
        "budget",
        "actual",
        "variance"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "dso",
      "description": "دورهٔ وصول مطالبات",
      "formula": "مطالبات / فروش روزانه",
      "unit": "روز",
      "dimensions": [
        "customer",
        "period"
      ]
    },
    {
      "metric": "cash_balance",
      "description": "موجودی نقد پایان دوره",
      "formula": "جمع ورودی و خروجی‌های نقد",
      "unit": "میلیون تومان",
      "dimensions": [
        "period"
      ]
    }
  ],
  "business_context": [
    "شرکت تولیدی-بازرگانی میانه‌حجم؛ فروش عمدتاً نسیه به شرکت‌های صنعتی و بخشی خرد",
    "دورهٔ حسابداری ماهانه؛ گزارش‌ها تا پایان همان ماه در دسترس‌اند",
    "تأمین مالی اصلی از تسهیلات بانکی کوتاه‌مدت و اعتبار تأمین‌کنندگان"
  ]
}

