تصویر سودآوری سه‌ماههٔ دوم را می‌خواهم؛ کدام خط یا محصول دارد سود ما را پایین می‌کشد؟ (مدیر مالی — صنایع شیمیایی)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "sales_by_product",
      "description": "فروش و حاشیه به تفکیک محصول",
      "dimensions": [
        "product",
        "period"
      ],
      "measures": [
        "sales",
        "gross_margin_pct"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "gross_margin",
      "description": "حاشیهٔ ناخالص",
      "formula": "(فروش - بهای تمام‌شده) / فروش",
      "unit": "درصد",
      "dimensions": [
        "product",
        "period"
      ]
    }
  ],
  "business_context": [
    "شرکت تولیدی-بازرگانی میانه‌حجم؛ فروش عمدتاً نسیه به شرکت‌های صنعتی و بخشی خرد",
    "دورهٔ حسابداری ماهانه؛ گزارش‌ها تا پایان همان ماه در دسترس‌اند"
  ]
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "sales_by_product",
